"""Typed records used by every stage of the pipeline (spec Section 6).

All records are pydantic models so that retrieval, corruption, decoding and
evaluation are auditable, serialisable and validated at the boundary.

Conventions
-----------
* Timestamps are ISO-8601 strings in UTC, generated by :func:`utc_now_iso`.
* ``extra="forbid"`` everywhere: an unexpected field is a bug, not something to
  drop silently.
* Records are frozen where they represent evidence (``Fact``, ``EntityRecord``)
  so the corruption engine cannot mutate retrieved facts in place.
"""

from __future__ import annotations

import hashlib
import json
import time
from datetime import datetime, timezone
from enum import Enum
from typing import Any, Literal

from pydantic import BaseModel, ConfigDict, Field, field_validator, model_validator

__all__ = [
    "utc_now_iso",
    "stable_id",
    "EntityMention",
    "EntityRecord",
    "Fact",
    "CorruptionRecord",
    "CorruptionResult",
    "Example",
    "GenerationParams",
    "LatencyBreakdown",
    "GenerationRecord",
    "ClaimRecord",
    "ClaimJudgement",
    "JudgeVerdict",
    "ExampleMetrics",
    "AggregateMetrics",
    "RunManifest",
    "Status",
]


def utc_now_iso() -> str:
    """Current UTC time as an ISO-8601 string with a ``Z`` suffix."""
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")


def stable_id(*parts: Any, length: int = 16) -> str:
    """Deterministic short id (sha1) built from arbitrary parts.

    Used to give facts, examples and corruption audit entries reproducible ids
    so that a metric can always be traced back to the record that produced it.
    """
    payload = json.dumps([str(p) for p in parts], ensure_ascii=False, sort_keys=True)
    return hashlib.sha1(payload.encode("utf-8")).hexdigest()[:length]


class Status(str, Enum):
    """Outcome of processing one example."""

    OK = "ok"
    DEGRADED = "degraded"  # completed, but a component fell back (e.g. no facts)
    SKIPPED = "skipped"
    ERROR = "error"


# ---------------------------------------------------------------------------
# Entities
# ---------------------------------------------------------------------------


class EntityMention(BaseModel):
    """A surface mention found in a prompt (spec 6.1 / 7.1)."""

    model_config = ConfigDict(extra="forbid")

    mention: str
    start: int = Field(ge=0)
    end: int = Field(gt=0)
    label: str | None = None
    confidence: float = Field(default=1.0, ge=0.0, le=1.0)
    source: str = "rule"  # which NER backend produced it
    context: str | None = None  # local window used for disambiguation

    @model_validator(mode="after")
    def _check_offsets(self) -> EntityMention:
        if self.end <= self.start:
            raise ValueError(f"end ({self.end}) must be greater than start ({self.start})")
        if not self.mention.strip():
            raise ValueError("mention text must be non-empty")
        return self

    @property
    def length(self) -> int:
        return self.end - self.start


class EntityRecord(BaseModel):
    """A mention linked to a canonical knowledge-base entity (spec 6.1).

    ``entity_id`` is ``None`` when linking failed or was below the confidence
    threshold: the mention is preserved as *unlinked* rather than dropped or
    guessed (spec 7.2).
    """

    model_config = ConfigDict(extra="forbid")

    mention: str
    entity_id: str | None = None
    label: str | None = None
    description: str | None = None
    linking_confidence: float = Field(default=0.0, ge=0.0, le=1.0)
    link_method: str = "unknown"  # exact_label | search | mock | unresolved | ...
    aliases: list[str] = Field(default_factory=list)
    source: str = "unknown"
    start: int | None = None
    end: int | None = None
    candidates: list[dict[str, Any]] = Field(default_factory=list)

    @property
    def is_linked(self) -> bool:
        return self.entity_id is not None

    @property
    def display(self) -> str:
        return self.label or self.mention


# ---------------------------------------------------------------------------
# Facts
# ---------------------------------------------------------------------------


class Qualifier(BaseModel):
    """A Wikidata-style qualifier attached to a statement (spec 6.2)."""

    model_config = ConfigDict(extra="forbid")

    predicate_id: str
    predicate_label: str | None = None
    value: str
    value_type: Literal["entity", "literal"] = "literal"
    value_id: str | None = None


class Fact(BaseModel):
    """A single structured subject-predicate-object fact (spec 6.2).

    Facts are frozen: the corruption engine must produce *new* records, which is
    how "never mutate the original retrieved records in place" (spec 8.2) is
    enforced structurally instead of by convention.
    """

    model_config = ConfigDict(extra="forbid", frozen=True)

    fact_id: str = ""
    subject_id: str
    subject_label: str
    predicate_id: str
    predicate_label: str | None = None
    object_id: str | None = None
    object_label: str
    object_type: Literal["entity", "literal", "time", "quantity"] = "entity"
    object_datatype: str | None = None  # e.g. "wikibase-item", "time", "quantity"
    qualifiers: tuple[Qualifier, ...] = ()
    source: str = "unknown"
    source_url: str | None = None
    retrieved_at: str = Field(default_factory=utc_now_iso)
    confidence: float = Field(default=1.0, ge=0.0, le=1.0)
    rank: str | None = None  # preferred | normal | deprecated
    metadata: dict[str, Any] = Field(default_factory=dict)

    @model_validator(mode="after")
    def _fill_id(self) -> Fact:
        if not self.fact_id:
            object.__setattr__(
                self,
                "fact_id",
                stable_id(
                    self.subject_id,
                    self.predicate_id,
                    self.object_id or self.object_label,
                    self.source,
                ),
            )
        if not self.subject_label.strip() or not self.object_label.strip():
            raise ValueError("fact subject_label and object_label must be non-empty")
        return self

    def as_triple(self) -> tuple[str, str, str]:
        return (self.subject_label, self.predicate_label or self.predicate_id, self.object_label)

    def render(self, line_format: str = "- {subject} | {predicate} | {object}") -> str:
        """Render one fact line for a context block (same wording for both branches)."""
        return line_format.format(
            subject=self.subject_label,
            predicate=self.predicate_label or self.predicate_id,
            object=self.object_label,
            subject_id=self.subject_id,
            predicate_id=self.predicate_id,
            object_id=self.object_id or "",
            source=self.source,
        )

    def with_updates(self, **changes: Any) -> Fact:
        """Return a *new* fact with fields replaced (originals stay untouched)."""
        return self.model_copy(update=changes)


# ---------------------------------------------------------------------------
# Corruption
# ---------------------------------------------------------------------------


class CorruptionRecord(BaseModel):
    """Audit entry for one altered/skipped fact (spec 6.3)."""

    model_config = ConfigDict(extra="forbid")

    original_fact_id: str
    corruption_type: str
    original_object: str
    corrupted_object: str | None = None
    original_subject: str | None = None
    corrupted_subject: str | None = None
    corruption_source: str = "controlled synthetic corruption"
    random_seed: int | None = None
    is_corrupted: bool = True
    skipped_reason: str | None = None
    corrupted_fact_id: str | None = None
    qualifiers_preserved: bool = True

    @model_validator(mode="after")
    def _check(self) -> CorruptionRecord:
        if self.is_corrupted:
            if self.corruption_type == "omission":
                # The omission control removes a fact instead of falsifying it, so
                # there is deliberately no corrupted value to record.
                if self.corrupted_object is not None:
                    raise ValueError("an omission record must not carry a corrupted_object")
                return self
            if self.corruption_type == "entity_substitution":
                if not self.original_subject or not self.corrupted_subject:
                    raise ValueError("entity substitution must record original_subject and corrupted_subject")
                if self.original_subject.strip() == self.corrupted_subject.strip():
                    raise ValueError("entity substitution must change the subject label")
                return self
            if self.corrupted_object is None:
                raise ValueError("a corrupted record must record corrupted_object")
            if self.corrupted_object.strip() == self.original_object.strip():
                raise ValueError(
                    "corrupted_object must differ from original_object "
                    f"(both {self.original_object!r}) for fact {self.original_fact_id}"
                )
        elif not self.skipped_reason:
            raise ValueError("an uncorrupted/omitted record must explain why in skipped_reason")
        return self


class CorruptionResult(BaseModel):
    """Everything the pipeline needs to know about one corruption call."""

    model_config = ConfigDict(extra="forbid")

    original_facts: tuple[Fact, ...] = ()
    corrupted_facts: tuple[Fact, ...] = ()
    audit: tuple[CorruptionRecord, ...] = ()
    strategy: str = "none"
    corruption_rate: float = 0.0
    seed: int = 0
    selected_count: int = 0
    changed_count: int = 0
    omitted_count: int = 0
    skipped_count: int = 0
    notes: tuple[str, ...] = ()

    @property
    def summary(self) -> dict[str, Any]:
        return {
            "strategy": self.strategy,
            "corruption_rate": self.corruption_rate,
            "seed": self.seed,
            "n_original": len(self.original_facts),
            "n_contrast": len(self.corrupted_facts),
            "selected": self.selected_count,
            "changed": self.changed_count,
            "omitted": self.omitted_count,
            "skipped": self.skipped_count,
            "notes": list(self.notes),
        }


# ---------------------------------------------------------------------------
# Data examples
# ---------------------------------------------------------------------------


class Evidence(BaseModel):
    """A supporting passage used by the evaluator (never used as generation input
    unless explicitly enabled by the experiment)."""

    model_config = ConfigDict(extra="forbid")

    text: str
    source: str = "unknown"
    url: str | None = None
    sentence_index: int | None = None
    label: str | None = None  # e.g. SUPPORTS / REFUTES for FEVER


class Example(BaseModel):
    """One evaluation example (spec 11 / data/README.md envelope)."""

    model_config = ConfigDict(extra="forbid")

    example_id: str
    prompt: str
    dataset: str
    split: str = "test"
    task: Literal["generation", "halueval_detection", "fever_claims"] = "generation"
    reference: str | None = None
    evidence: list[Evidence] = Field(default_factory=list)
    gold_labels: dict[str, Any] = Field(default_factory=dict)
    metadata: dict[str, Any] = Field(default_factory=dict)
    provenance: dict[str, Any] = Field(default_factory=dict)

    @field_validator("prompt")
    @classmethod
    def _non_empty_prompt(cls, value: str) -> str:
        if not value.strip():
            raise ValueError("example prompt must be non-empty")
        return value

    @property
    def reference_text(self) -> str | None:
        return self.reference

    @property
    def entity_hint(self) -> str | None:
        """Optional entity the example is about (helps the linker disambiguate)."""
        for key in ("entity", "entity_name", "title"):
            value = self.metadata.get(key)
            if isinstance(value, str) and value.strip():
                return value
        return None


# ---------------------------------------------------------------------------
# Decoding / generation
# ---------------------------------------------------------------------------


class GenerationParams(BaseModel):
    """The decoding parameters actually used for one generation."""

    model_config = ConfigDict(extra="forbid")

    mode: str
    variant: str
    alpha: float
    max_new_tokens: int
    min_new_tokens: int = 0
    do_sample: bool
    temperature: float
    top_p: float
    top_k: int
    repetition_penalty: float = 1.0
    no_repeat_ngram_size: int = 0
    use_cache: bool = True
    seed: int
    stop_sequences: list[str] = Field(default_factory=list)
    adaptive_plausibility: bool = False
    plausibility_epsilon: float = 0.1
    contrast_warmup_tokens: int = 0
    amateur_model_id: str | None = None


class LatencyBreakdown(BaseModel):
    """Wall-clock timings, all in seconds (spec 10.4 / 12.3)."""

    model_config = ConfigDict(extra="forbid")

    model_load_s: float = 0.0
    # Only used by the "amateur model" ablation (decoding.amateur_model_id): the
    # second model's load time is measured separately so it cannot be mistaken for
    # generation cost.
    contrast_model_load_s: float = 0.0
    entity_extraction_s: float = 0.0
    entity_linking_s: float = 0.0
    fact_retrieval_s: float = 0.0
    corruption_s: float = 0.0
    context_build_s: float = 0.0
    generation_s: float = 0.0
    total_s: float = 0.0
    peak_memory_mb: float | None = None
    device: str | None = None
    synchronized: bool = False

    def add(self, **increments: float) -> None:
        for key, value in increments.items():
            if not hasattr(self, key):
                raise KeyError(f"unknown latency field {key!r}")
            setattr(self, key, float(getattr(self, key)) + float(value))

    def recompute_total(self) -> float:
        """Total = every measured component (so the components are auditable)."""
        self.total_s = float(
            self.model_load_s
            + self.contrast_model_load_s
            + self.entity_extraction_s
            + self.entity_linking_s
            + self.fact_retrieval_s
            + self.corruption_s
            + self.context_build_s
            + self.generation_s
        )
        return self.total_s


class GenerationRecord(BaseModel):
    """The complete, traceable record of one generated answer (spec 6.4)."""

    model_config = ConfigDict(extra="forbid")

    # identity / provenance
    example_id: str
    run_id: str = ""
    condition: str = ""
    prompt: str
    prompt_sha256: str = ""
    dataset: str = "unknown"
    split: str = "unknown"
    task: str = "generation"
    model_id: str = ""
    model_revision: str | None = None
    tokenizer_id: str = ""
    tokenizer_revision: str | None = None
    is_toy_model: bool = False
    device: str = ""
    dtype: str = ""
    seed: int = 0

    # decoding
    mode: str = "baseline"
    variant: str = "contrastive_logprob"
    alpha: float = 0.0
    params: GenerationParams | None = None
    contrast_applied: bool = False
    degraded_reason: str | None = None

    # knowledge
    entities: list[EntityRecord] = Field(default_factory=list)
    facts: list[Fact] = Field(default_factory=list)
    corruption: CorruptionResult | None = None
    base_context: str = ""
    contrast_context: str | None = None
    contrast_prompt_tokens: int | None = None

    # output
    answer: str = ""
    raw_answer: str = ""
    generated_token_ids: list[int] = Field(default_factory=list)
    stop_reason: str = "max_new_tokens"
    input_tokens: int = 0
    output_tokens: int = 0

    # measurement + status
    latency: LatencyBreakdown = Field(default_factory=LatencyBreakdown)
    status: Status = Status.OK
    error: str | None = None
    reference: str | None = None
    metadata: dict[str, Any] = Field(default_factory=dict)
    timestamp: str = Field(default_factory=utc_now_iso)

    @model_validator(mode="after")
    def _consistency(self) -> GenerationRecord:
        if not self.prompt_sha256:
            object.__setattr__(
                self, "prompt_sha256", hashlib.sha256(self.prompt.encode("utf-8")).hexdigest()
            )
        if self.mode == "factanchor" and self.alpha > 0 and self.status is Status.OK and not self.contrast_applied:
            # A silent no-op contrast would make the metric table misleading.
            object.__setattr__(self, "status", Status.DEGRADED)
            if not self.degraded_reason:
                object.__setattr__(self, "degraded_reason", "contrast_not_applied")
        return self

    @property
    def ms_per_token(self) -> float | None:
        if self.output_tokens <= 0:
            return None
        return 1000.0 * self.latency.generation_s / self.output_tokens

    def to_jsonl(self) -> str:
        return self.model_dump_json()


# ---------------------------------------------------------------------------
# Metrics
# ---------------------------------------------------------------------------


class ClaimRecord(BaseModel):
    """An atomic claim extracted from an answer (spec 12.1)."""

    model_config = ConfigDict(extra="forbid")

    claim_id: str
    text: str
    source_sentence: str = ""
    sentence_index: int = 0
    entities: list[str] = Field(default_factory=list)
    numbers: list[str] = Field(default_factory=list)
    extractor: str = "rule"


class JudgeVerdict(BaseModel):
    """One adjudication of a claim against evidence."""

    model_config = ConfigDict(extra="forbid")

    claim_id: str
    label: Literal["supported", "contradicted", "unsupported", "no_evidence"]
    score: float = Field(default=0.0, ge=0.0, le=1.0)
    evidence_used: list[str] = Field(default_factory=list)
    rationale: str = ""
    judge: str = "unknown"


class ClaimJudgement(BaseModel):
    """All claims of one answer plus their verdicts."""

    model_config = ConfigDict(extra="forbid")

    claims: list[ClaimRecord] = Field(default_factory=list)
    verdicts: list[JudgeVerdict] = Field(default_factory=list)
    judge: str = "unknown"

    @property
    def counts(self) -> dict[str, int]:
        out = {"supported": 0, "contradicted": 0, "unsupported": 0, "no_evidence": 0}
        for verdict in self.verdicts:
            out[verdict.label] = out.get(verdict.label, 0) + 1
        return out


class ExampleMetrics(BaseModel):
    """Per-example metrics; every number is computed from saved artifacts."""

    model_config = ConfigDict(extra="forbid")

    example_id: str
    condition: str = ""
    mode: str = "baseline"
    n_claims: int = 0
    n_supported: int = 0
    n_contradicted: int = 0
    n_unsupported: int = 0
    n_no_evidence: int = 0
    claim_support_rate: float | None = None
    hallucination_rate: float | None = None
    contradiction_rate: float | None = None
    evidence_coverage: float | None = None
    factscore: float | None = None
    bertscore_f1: float | None = None
    rouge_l: float | None = None
    exact_match: float | None = None
    token_f1: float | None = None
    output_tokens: int = 0
    generation_s: float = 0.0
    total_s: float = 0.0
    ms_per_token: float | None = None
    status: str = "ok"
    notes: list[str] = Field(default_factory=list)


class AggregateMetrics(BaseModel):
    """Aggregate metrics with explicit sample sizes and uncertainty (spec 12.4)."""

    model_config = ConfigDict(extra="forbid")

    condition: str = ""
    mode: str = ""
    variant: str = ""
    n_examples: int = 0
    n_ok: int = 0
    n_degraded: int = 0
    n_skipped: int = 0
    n_errors: int = 0
    n_with_claims: int = 0
    mean_claim_support_rate: float | None = None
    mean_hallucination_rate: float | None = None
    mean_contradiction_rate: float | None = None
    mean_evidence_coverage: float | None = None
    mean_factscore: float | None = None
    mean_bertscore_f1: float | None = None
    mean_rouge_l: float | None = None
    mean_exact_match: float | None = None
    mean_token_f1: float | None = None
    ci: dict[str, list[float]] = Field(default_factory=dict)
    latency: dict[str, float] = Field(default_factory=dict)
    latency_by_condition: dict[str, dict[str, float]] = Field(default_factory=dict)
    definitions: dict[str, str] = Field(default_factory=dict)
    judge: str = ""
    evidence_source: str = ""
    notes: list[str] = Field(default_factory=list)


class RunManifest(BaseModel):
    """Provenance for one run directory (spec 16)."""

    model_config = ConfigDict(extra="forbid")

    run_id: str
    run_name: str = ""
    condition: str = ""
    created_at: str = Field(default_factory=utc_now_iso)
    git_hash: str | None = None
    git_dirty: bool | None = None
    python_version: str = ""
    platform: str = ""
    hardware: dict[str, Any] = Field(default_factory=dict)
    library_versions: dict[str, str] = Field(default_factory=dict)
    model_id: str = ""
    model_revision: str | None = None
    tokenizer_id: str = ""
    tokenizer_revision: str | None = None
    is_toy_model: bool = False
    device: str = ""
    dtype: str = ""
    seed: int = 0
    dataset: str = ""
    dataset_split: str = ""
    n_examples: int = 0
    knowledge_provider: str = ""
    knowledge_source: str = ""
    corruption_strategy: str = ""
    corruption_rate: float = 0.0
    config_path: str | None = None
    config_hash: str = ""
    warnings: list[str] = Field(default_factory=list)
    notes: list[str] = Field(default_factory=list)

    @field_validator("hardware")
    @classmethod
    def _json_safe(cls, value: dict[str, Any]) -> dict[str, Any]:
        return {k: (v if isinstance(v, (str, int, float, bool, list, dict, type(None))) else str(v)) for k, v in value.items()}


class TokenStep(BaseModel):
    """Optional per-step diagnostic (spec 3.2 item 8, disable by default)."""

    model_config = ConfigDict(extra="forbid")

    step: int
    token_id: int
    token: str
    base_logprob: float
    contrast_logprob: float | None = None
    score: float
    entropy_base: float | None = None
    contrast_applied: bool = False
    score_top1_gap: float | None = None
    timestamp_monotonic: float = Field(default_factory=time.monotonic)
